import type { Product } from "@/types/product";

import { cleanImageUrls } from "@/utils/format";

const GENERATED_TITLE = /^title-[0-9a-f-]{36}$/i;
const GENERATED_DESCRIPTION = /^desc-[0-9a-f-]{36}$/i;

const PLACEHOLDER_IMAGE_HOSTS = [
  "placehold.co",
  "via.placeholder.com",
  "placeholder.com",
  "dummyimage.com",
  "picsum.photos",
  "fastly.picsum.photos",
];

/** Auto-generated rows from shared Escuela JS student/test submissions. */
export function isAutoGeneratedProduct(product: Product): boolean {
  return (
    GENERATED_TITLE.test(product.title.trim()) ||
    GENERATED_DESCRIPTION.test(product.description.trim())
  );
}

/** Keep the customer storefront aligned with real catalog items only. */
export function filterStorefrontProducts(products: Product[]): Product[] {
  return products.filter((product) => !isAutoGeneratedProduct(product));
}

export function getProductDisplayTitle(product: Product): string {
  if (!isAutoGeneratedProduct(product)) return product.title;
  const category = product.category?.name ?? "Product";
  return `${category} item #${product.id}`;
}

function categoryImageLabel(product: Product): string {
  const name = product.category?.name?.trim();
  if (name) return name.slice(0, 24);
  if (!isAutoGeneratedProduct(product)) {
    return product.title.slice(0, 24);
  }
  return "Product";
}

function categoryPlaceholderImage(product: Product): string {
  const label = encodeURIComponent(categoryImageLabel(product));
  return `https://placehold.co/600x600/e2e8f0/1e293b?text=${label}`;
}

function isPlaceholderImageUrl(url: string): boolean {
  try {
    const { hostname } = new URL(url);
    return PLACEHOLDER_IMAGE_HOSTS.some(
      (host) => hostname === host || hostname.endsWith(`.${host}`),
    );
  } catch {
    return false;
  }
}

export function getProductImageUrl(product: Product): string | undefined {
  const images = cleanImageUrls(product.images);
  const first = images[0];

  if (!first) {
    return categoryPlaceholderImage(product);
  }

  if (isPlaceholderImageUrl(first)) {
    return categoryPlaceholderImage(product);
  }

  return first;
}

export function getProductImageGallery(product: Product): string[] {
  const images = cleanImageUrls(product.images);
  if (!images.length) return [categoryPlaceholderImage(product)];
  return images.map((url) =>
    isPlaceholderImageUrl(url) ? categoryPlaceholderImage(product) : url,
  );
}
